window.QB_TIU_B11 = [
{id:"TIU-1621", q:"Sinonim kata NESTAPA adalah ....", opts:["sengsara","bahagia","makmur","sejahtera","sentosa"], a:0, ex:"Nestapa berarti penderitaan atau kesengsaraan. Sinonim kata nestapa adalah sengsara."},
{id:"TIU-1622", q:"Sinonim kata SENTOSA adalah ....", opts:["kacau","tenteram","rusuh","genting","gawat"], a:1, ex:"Sentosa berarti aman dan tenteram. Sinonim kata sentosa adalah tenteram."},
{id:"TIU-1623", q:"Sinonim kata DUNGU adalah ....", opts:["cerdas","pandai","bebal","bijak","cerdik"], a:2, ex:"Dungu berarti bodoh atau tidak cerdas. Sinonim kata dungu adalah bebal."},
{id:"TIU-1624", q:"Sinonim kata DEGIL adalah ....", opts:["patuh","taat","penurut","bandel","jinak"], a:3, ex:"Degil berarti keras kepala dan tidak mau menuruti nasihat. Sinonim kata degil adalah bandel."},
{id:"TIU-1625", q:"Sinonim kata PEKAK adalah ....", opts:["peka","awas","siaga","waspada","tuli"], a:4, ex:"Pekak berarti tidak dapat mendengar. Sinonim kata pekak adalah tuli."},
{id:"TIU-1626", q:"Sinonim kata CEBOL adalah ....", opts:["kerdil","jangkung","tinggi","raksasa","besar"], a:0, ex:"Cebol berarti berukuran kecil atau kerdil. Sinonim kata cebol adalah kerdil."},
{id:"TIU-1627", q:"Sinonim kata JELUK adalah ....", opts:["dangkal","dalam","cetek","sempit","pendek"], a:1, ex:"Jeluk berarti dalam (tentang air atau pengetahuan). Sinonim kata jeluk adalah dalam."},
{id:"TIU-1628", q:"Sinonim kata TASIK adalah ....", opts:["sungai","laut","danau","rawa","selat"], a:2, ex:"Tasik berarti danau. Sinonim kata tasik adalah danau."},
{id:"TIU-1629", q:"Sinonim kata NUSA adalah ....", opts:["benua","daratan","semenanjung","pulau","tanjung"], a:3, ex:"Nusa berarti pulau. Sinonim kata nusa adalah pulau."},
{id:"TIU-1630", q:"Sinonim kata SEGARA adalah ....", opts:["darat","sungai","danau","selat","laut"], a:4, ex:"Segara berarti laut atau samudra. Sinonim kata segara adalah laut."},
{id:"TIU-1631", q:"Sinonim kata SWARGA adalah ....", opts:["surga","neraka","jahanam","kubur","siksa"], a:0, ex:"Swarga berarti surga. Sinonim kata swarga adalah surga."},
{id:"TIU-1632", q:"Sinonim kata JAHANAM adalah ....", opts:["surga","neraka","firdaus","kahyangan","nirwana"], a:1, ex:"Jahanam berarti neraka. Sinonim kata jahanam adalah neraka."},
{id:"TIU-1633", q:"Sinonim kata PUSARA adalah ....", opts:["istana","rumah","kubur","tenda","gubuk"], a:2, ex:"Pusara berarti kubur atau makam. Sinonim kata pusara adalah kubur."},
{id:"TIU-1634", q:"Sinonim kata BERTUAH adalah ....", opts:["sial","apes","celaka","keramat","malang"], a:3, ex:"Bertuah berarti memiliki tuah, yakni kesaktian. Sinonim kata bertuah adalah keramat."},
{id:"TIU-1635", q:"Sinonim kata TAKZIM adalah ....", opts:["lancang","biadab","kurang ajar","durhaka","hormat"], a:4, ex:"Takzim berarti hormat dan sopan. Sinonim kata takzim adalah hormat."},
{id:"TIU-1636", q:"Sinonim kata LUGAS adalah ....", opts:["terus terang","berbelit-belit","samar","kabur","tertutup"], a:0, ex:"Lugas berarti terus terang dan tidak berbelit-belit. Sinonim kata lugas adalah terus terang."},
{id:"TIU-1637", q:"Sinonim kata MUSTAJAB adalah ....", opts:["gagal","manjur","sia-sia","percuma","hampa"], a:1, ex:"Mustajab berarti manjur atau mujarab (tentang doa atau obat). Sinonim kata mustajab adalah manjur."},
{id:"TIU-1638", q:"Sinonim kata GUNDAH adalah ....", opts:["tenang","tenteram","risau","kalem","santai"], a:2, ex:"Gundah berarti gelisah atau risau. Sinonim kata gundah adalah risau."},
{id:"TIU-1639", q:"Sinonim kata WASWAS adalah ....", opts:["yakin","percaya","tenang","cemas","mantap"], a:3, ex:"Waswas berarti cemas dan khawatir. Sinonim kata waswas adalah cemas."},
{id:"TIU-1640", q:"Sinonim kata MURAM adalah ....", opts:["ceria","riang","gembira","cerah","murung"], a:4, ex:"Muram berarti murung atau tidak cerah (tentang wajah atau cuaca). Sinonim kata muram adalah murung."},
{id:"TIU-1641", q:"Antonim kata GAIB adalah ....", opts:["kasatmata","samar","kabur","buram","gelap"], a:0, ex:"Gaib berarti tidak kasatmata. Antonim kata gaib adalah kasatmata."},
{id:"TIU-1642", q:"Antonim kata FANA adalah ....", opts:["sementara","kekal","temporer","singkat","insidental"], a:1, ex:"Fana berarti tidak kekal. Antonim kata fana adalah kekal."},
{id:"TIU-1643", q:"Antonim kata LABIL adalah ....", opts:["goyah","goyang","stabil","guncang","oleng"], a:2, ex:"Labil berarti tidak stabil atau mudah goyah. Antonim kata labil adalah stabil."},
{id:"TIU-1644", q:"Antonim kata KIKIR adalah ....", opts:["pelit","bakhil","medit","pemurah","serakah"], a:3, ex:"Kikir berarti pelit. Antonim kata kikir adalah pemurah."},
{id:"TIU-1645", q:"Antonim kata BOROS adalah ....", opts:["royal","pemboros","berlebihan","foya-foya","hemat"], a:4, ex:"Boros berarti tidak hemat. Antonim kata boros adalah hemat."},
{id:"TIU-1646", q:"Antonim kata MACET adalah ....", opts:["lancar","tersendat","buntu","tersumbat","mandek"], a:0, ex:"Macet berarti tersendat atau tidak lancar. Antonim kata macet adalah lancar."},
{id:"TIU-1647", q:"Antonim kata DERAS adalah ....", opts:["kencang","pelan","laju","cepat","lebat"], a:1, ex:"Deras berarti kencang (tentang aliran air). Antonim kata deras adalah pelan."},
{id:"TIU-1648", q:"Antonim kata GEGABAH adalah ....", opts:["ceroboh","sembrono","berhati-hati","tergopoh","terburu-buru"], a:2, ex:"Gegabah berarti terburu-buru tanpa pertimbangan. Antonim kata gegabah adalah berhati-hati."},
{id:"TIU-1649", q:"Antonim kata LALAI adalah ....", opts:["lengah","abai","lupa","waspada","khilaf"], a:3, ex:"Lalai berarti lengah atau tidak waspada. Antonim kata lalai adalah waspada."},
{id:"TIU-1650", q:"Antonim kata CEROBOH adalah ....", opts:["sembrono","gegabah","teledor","lalai","cermat"], a:4, ex:"Ceroboh berarti tidak cermat. Antonim kata ceroboh adalah cermat."},
{id:"TIU-1651", q:"Antonim kata SIGAP adalah ....", opts:["lamban","cekatan","gesit","lincah","cepat"], a:0, ex:"Sigap berarti cekatan dan tangkas. Antonim kata sigap adalah lamban."},
{id:"TIU-1652", q:"Antonim kata LAMBAN adalah ....", opts:["lambat","cepat","lelet","lesu","lunglai"], a:1, ex:"Lamban berarti lambat. Antonim kata lamban adalah cepat."},
{id:"TIU-1653", q:"Antonim kata GULITA adalah ....", opts:["gelap","kelam","terang","suram","pekat"], a:2, ex:"Gulita berarti gelap gulita. Antonim kata gulita adalah terang."},
{id:"TIU-1654", q:"Antonim kata LELAP adalah ....", opts:["tertidur","terpejam","pulas","terjaga","mendengkur"], a:3, ex:"Lelap berarti tertidur nyenyak. Antonim kata lelap adalah terjaga."},
{id:"TIU-1655", q:"Antonim kata SIUMAN adalah ....", opts:["sadar","terjaga","bangun","melek","pingsan"], a:4, ex:"Siuman berarti sadar kembali. Antonim kata siuman adalah pingsan."},
{id:"TIU-1656", q:"Antonim kata LESU adalah ....", opts:["segar","lunglai","lemas","loyo","letih"], a:0, ex:"Lesu berarti tidak bertenaga. Antonim kata lesu adalah segar."},
{id:"TIU-1657", q:"Antonim kata TABAH adalah ....", opts:["sabar","putus asa","tegar","kukuh","teguh"], a:1, ex:"Tabah berarti sabar dan kuat menghadapi cobaan. Antonim kata tabah adalah putus asa."},
{id:"TIU-1658", q:"Antonim kata GUGUP adalah ....", opts:["grogi","gelisah","tenang","cemas","demam panggung"], a:2, ex:"Gugup berarti tidak tenang. Antonim kata gugup adalah tenang."},
{id:"TIU-1659", q:"Antonim kata TEGANG adalah ....", opts:["kaku","stres","cemas","santai","gugup"], a:3, ex:"Tegang berarti tidak santai atau kaku. Antonim kata tegang adalah santai."},
{id:"TIU-1660", q:"Antonim kata MINDER adalah ....", opts:["rendah diri","pemalu","penakut","tertutup","percaya diri"], a:4, ex:"Minder berarti rendah diri. Antonim kata minder adalah percaya diri."},
{id:"TIU-1661", q:"Aktuaris : Risiko = Kurator : ....", opts:["Artefak","Pameran","Museum","Lelang","Kolektor"], a:1, ex:"Aktuaris adalah ahli yang menganalisis risiko, sedangkan kurator adalah ahli yang mengelola pameran."},
{id:"TIU-1662", q:"Numismatis : Koin = Filatelis : ....", opts:["Perangko","Amplop","Surat","Koin","Pos"], a:0, ex:"Numismatis adalah pengoleksi sekaligus pengkaji koin, sedangkan filatelis adalah pengoleksi perangko."},
{id:"TIU-1663", q:"Observatorium : Astronom = Herbarium : ....", opts:["Dokter","Insinyur","Guru","Botanis","Nelayan"], a:3, ex:"Observatorium adalah tempat kerja astronom, sedangkan herbarium adalah tempat kerja botanis (ahli tumbuhan)."},
{id:"TIU-1664", q:"Terarium : Reptil = Apiari : ....", opts:["Madu","Tawon","Lebah","Nektar","Sarang"], a:2, ex:"Terarium adalah wadah pemeliharaan reptil, sedangkan apiari adalah tempat budidaya lebah."},
{id:"TIU-1665", q:"Wol : Domba = Mutiara : ....", opts:["Ikan","Ubur-ubur","Bintang laut","Gurita","Tiram"], a:4, ex:"Wol dihasilkan oleh domba, sedangkan mutiara dihasilkan oleh tiram."},
{id:"TIU-1666", q:"Pulp : Kertas = Kakao : ....", opts:["Kopi","Gula","Cokelat","Kakao","Permen"], a:2, ex:"Pulp adalah bahan baku pembuatan kertas, sedangkan kakao adalah bahan baku pembuatan cokelat."},
{id:"TIU-1667", q:"Palet : Pelukis = Tripod : ....", opts:["Fotografer","Penulis","Penyanyi","Penari","Pelukis"], a:0, ex:"Palet adalah alat kerja pelukis, sedangkan tripod adalah alat kerja fotografer."},
{id:"TIU-1668", q:"Mikroskop : Mikrobiolog = Teleskop : ....", opts:["Astrolog","Astronom","Kosmolog","Fisikawan","Navigator"], a:1, ex:"Mikroskop adalah alat kerja mikrobiolog, sedangkan teleskop adalah alat kerja astronom."},
{id:"TIU-1669", q:"Sekstan : Nahkoda = Teodolit : ....", opts:["Tukang","Mandor","Arsitek","Kontraktor","Surveyor"], a:4, ex:"Sekstan adalah alat navigasi nahkoda, sedangkan teodolit adalah alat ukur surveyor."},
{id:"TIU-1670", q:"Epigraf : Prasasti = Paleograf : ....", opts:["Prasasti","Fosil","Artefak","Naskah kuno","Makam"], a:3, ex:"Epigraf adalah ahli yang mengkaji prasasti, sedangkan paleograf adalah ahli yang mengkaji naskah kuno."},
{id:"TIU-1671", q:"Niscaya : Pasti = Fana : ....", opts:["Abadi","Kekal","Sementara","Selamanya","Pasti"], a:2, ex:"Niscaya bersinonim dengan pasti, sedangkan fana bersinonim dengan sementara (tidak kekal)."},
{id:"TIU-1672", q:"Deduktif : Induktif = Homogen : ....", opts:["Heterogen","Seragam","Tunggal","Murni","Sama"], a:0, ex:"Deduktif berlawanan dengan induktif, sedangkan homogen berlawanan dengan heterogen."},
{id:"TIU-1673", q:"Simetris : Asimetris = Sinkron : ....", opts:["Serentak","Selaras","Terpadu","Stabil","Asinkron"], a:4, ex:"Simetris berlawanan dengan asimetris, sedangkan sinkron berlawanan dengan asinkron."},
{id:"TIU-1674", q:"Kekeringan : Paceklik = Erosi : ....", opts:["Longsor","Sedimentasi","Abrasi","Tanah","Batuan"], a:1, ex:"Kekeringan menyebabkan paceklik, sedangkan erosi menyebabkan sedimentasi (pengendapan material)."},
{id:"TIU-1675", q:"Hanggar : Pesawat = Dermaga : ....", opts:["Pesawat","Kereta","Bus","Kapal","Mobil"], a:3, ex:"Hanggar adalah tempat menyimpan pesawat, sedangkan dermaga adalah tempat bersandarnya kapal."},
{id:"TIU-1676", q:"Notaris : Akta = Koreografer : ....", opts:["Musik","Drama","Tari","Film","Lagu"], a:2, ex:"Notaris menghasilkan akta, sedangkan koreografer menciptakan tari."},
{id:"TIU-1677", q:"Luthier : Biola = Kartunis : ....", opts:["Karikatur","Novel","Puisi","Esai","Naskah"], a:0, ex:"Luthier adalah pembuat biola, sedangkan kartunis adalah pembuat karikatur."},
{id:"TIU-1678", q:"Barometer : Meteorolog = Sismograf : ....", opts:["Ahli cuaca","Geolog","Kartografer","Arkeolog","Seismolog"], a:4, ex:"Barometer adalah alat kerja meteorolog, sedangkan sismograf adalah alat kerja seismolog (ahli gempa bumi)."},
{id:"TIU-1679", q:"Implisit : Eksplisit = Kualitatif : ....", opts:["Deskriptif","Kuantitatif","Naratif","Subjektif","Teoretis"], a:1, ex:"Implisit berlawanan dengan eksplisit, sedangkan kualitatif berlawanan dengan kuantitatif."},
{id:"TIU-1680", q:"Bait : Puisi = Pasal : ....", opts:["Peraturan","Ketentuan","Ayat","Undang-undang","Hukum"], a:3, ex:"Bait adalah bagian dari puisi, sedangkan pasal adalah bagian dari undang-undang."},
{id:"TIU-1681", q:"2, 7, 22, 55, 118, ....", opts:["218","220","225","227","235"], a:3, ex:"Selisih tingkat 1: +5, +15, +33, +63. Selisih tingkat 2: +10, +18, +30 (bertambah 8). Selisih tingkat 3: +8, +12 (bertambah 4). Berikutnya tingkat 3 = +16, tingkat 2 = 30 + 16 = 46, tingkat 1 = 63 + 46 = 109. 118 + 109 = 227."},
{id:"TIU-1682", q:"2, 3, 1, 6, 6, 2, 18, 12, ....", opts:["3","6","4","5","8"], a:2, ex:"Tiga sub-deret berselang: sub-deret 1 (posisi 1,4,7): 2, 6, 18 (×3); sub-deret 2 (posisi 2,5,8): 3, 6, 12 (×2); sub-deret 3 (posisi 3,6,9): 1, 2, ... (×2). Suku berikutnya adalah sub-deret 3: 2 × 2 = 4."},
{id:"TIU-1683", q:"8, 19, 14, 31, 26, ....", opts:["52","57","50","60","55"], a:4, ex:"Operasi bergantian: 8 × 2 + 3 = 19; 19 − 5 = 14; 14 × 2 + 3 = 31; 31 − 5 = 26. Berikutnya × 2 + 3: 26 × 2 + 3 = 55."},
{id:"TIU-1684", q:"2, 9, 10, 65, 26, ....", opts:["217","208","215","226","200"], a:0, ex:"Pola berselang: posisi ganjil = n² + 1 (1²+1=2, 3²+1=10, 5²+1=26); posisi genap = n³ + 1 (2³+1=9, 4³+1=65). Suku ke-6: 6³ + 1 = 217."},
{id:"TIU-1685", q:"A, C, F, H, K, ....", opts:["L","M","N","O","K"], a:1, ex:"Lompatan huruf bergantian +2, +3: A +2 = C; C +3 = F; F +2 = H; H +3 = K. Berikutnya +2: K + 2 = M."},
{id:"TIU-1686", q:"1A, 3C, 7F, 13J, ....", opts:["19N","21P","23O","21O","17M"], a:3, ex:"Angka: 1, 3, 7, 13 (selisih +2, +4, +6, berikutnya +8 → 21). Huruf: A, C, F, J (lompat +2, +3, +4, berikutnya +5 → O). Suku berikutnya: 21O."},
{id:"TIU-1687", q:"6, 24, 60, 120, ....", opts:["180","200","210","216","240"], a:2, ex:"Pola n³ − n: 2³ − 2 = 6; 3³ − 3 = 24; 4³ − 4 = 60; 5³ − 5 = 120. Berikutnya: 6³ − 6 = 216 − 6 = 210."},
{id:"TIU-1688", q:"5, 7, 11, 16, 23, 25, 47, ....", opts:["32","34","36","31","43"], a:1, ex:"Dua sub-deret berselang: posisi ganjil 5, 11, 23, 47 (×2 + 1); posisi genap 7, 16, 25 (+9). Suku berikutnya adalah posisi genap: 25 + 9 = 34."},
{id:"TIU-1689", q:"4, 9, 19, 36, 62, ....", opts:["99","96","101","94","103"], a:0, ex:"Selisih tingkat 1: +5, +10, +17, +26. Selisih tingkat 2: +5, +7, +9 (deret ganjil, berikutnya +11). Selisih tingkat 1 berikutnya: 26 + 11 = 37. Suku berikutnya: 62 + 37 = 99."},
{id:"TIU-1690", q:"Z, X, U, Q, L, ....", opts:["G","E","F","H","D"], a:2, ex:"Huruf mundur dengan lompatan membesar: Z −2 = X; X −3 = U; U −4 = Q; Q −5 = L. Berikutnya −6: L − 6 = F."},
{id:"TIU-1691", q:"3, 7, 16, 35, ....", opts:["70","72","78","67","74"], a:4, ex:"Pola ×2 + n (n bertambah): 3 × 2 + 1 = 7; 7 × 2 + 2 = 16; 16 × 2 + 3 = 35. Berikutnya: 35 × 2 + 4 = 74."},
{id:"TIU-1692", q:"7, 26, 63, 124, ....", opts:["210","216","224","215","200"], a:3, ex:"Pola n³ − 1: 2³ − 1 = 7; 3³ − 1 = 26; 4³ − 1 = 63; 5³ − 1 = 124. Berikutnya: 6³ − 1 = 216 − 1 = 215."},
{id:"TIU-1693", q:"2B, 4D, 8G, 16K, ....", opts:["32O","32P","32Q","30P","36P"], a:1, ex:"Angka: 2, 4, 8, 16 (×2, berikutnya 32). Huruf: B, D, G, K (lompat +2, +3, +4, berikutnya +5 → P). Suku berikutnya: 32P."},
{id:"TIU-1694", q:"100, 3, 7, 90, 6, 14, 80, ....", opts:["12","10","14","11","16"], a:0, ex:"Tiga sub-deret berselang: 100, 90, 80 (−10); 3, 6, ... (×2); 7, 14, ... (×2). Setelah 80 (sub-deret 1), giliran sub-deret 2: 6 × 2 = 12."},
{id:"TIU-1695", q:"4, 13, 25, 76, 151, ....", opts:["450","453","454","452","456"], a:2, ex:"Operasi bergantian ×3 + 1 dan ×2 − 1: 4 × 3 + 1 = 13; 13 × 2 − 1 = 25; 25 × 3 + 1 = 76; 76 × 2 − 1 = 151. Berikutnya ×3 + 1: 151 × 3 + 1 = 454."},
{id:"TIU-1696", q:"A, D, B, E, C, ....", opts:["G","F","D","H","E"], a:1, ex:"Lompatan bergantian +3, −2: A +3 = D; D −2 = B; B +3 = E; E −2 = C. Berikutnya +3: C + 3 = F."},
{id:"TIU-1697", q:"2, 12, 36, 80, 150, ....", opts:["240","250","260","252","248"], a:3, ex:"Pola n³ + n²: 1³ + 1² = 2; 2³ + 2² = 12; 3³ + 3² = 36; 4³ + 4² = 80; 5³ + 5² = 150. Berikutnya: 6³ + 6² = 216 + 36 = 252."},
{id:"TIU-1698", q:"A, E, I, M, Q, ....", opts:["T","V","S","W","U"], a:4, ex:"Setiap huruf melompat 4 langkah: A +4 = E; E +4 = I; I +4 = M; M +4 = Q. Berikutnya: Q + 4 = U."},
{id:"TIU-1699", q:"1, 2, 5, 14, 41, ....", opts:["120","122","124","118","121"], a:1, ex:"Pola ×3 − 1: 1 × 3 − 1 = 2; 2 × 3 − 1 = 5; 5 × 3 − 1 = 14; 14 × 3 − 1 = 41. Berikutnya: 41 × 3 − 1 = 122."},
{id:"TIU-1700", q:"1, 3, 9, 21, 41, ....", opts:["69","73","71","68","75"], a:2, ex:"Selisih tingkat 1: +2, +6, +12, +20. Selisih tingkat 2: +4, +6, +8 (bertambah 2, berikutnya +10). Selisih tingkat 1 berikutnya: 20 + 10 = 30. Suku berikutnya: 41 + 30 = 71."},
{id:"TIU-1701", q:"2A, 3B, 5C, 7D, ....", opts:["11E","13E","11F","9E","11D"], a:0, ex:"Angka adalah bilangan prima berurutan: 2, 3, 5, 7 (berikutnya 11). Huruf adalah abjad berurutan: A, B, C, D (berikutnya E). Suku berikutnya: 11E."},
{id:"TIU-1702", q:"243, 81, 90, 30, 39, ....", opts:["12","14","15","13","10"], a:3, ex:"Operasi bergantian ÷3 dan +9: 243 ÷ 3 = 81; 81 + 9 = 90; 90 ÷ 3 = 30; 30 + 9 = 39. Berikutnya ÷3: 39 ÷ 3 = 13."},
{id:"TIU-1703", q:"5, 6, 10, 19, 35, 60, ....", opts:["90","95","100","85","96"], a:4, ex:"Selisih antar suku membentuk kuadrat sempurna: +1, +4, +9, +16, +25 (1² sampai 5²). Selisih berikutnya: 6² = 36. Suku berikutnya: 60 + 36 = 96."},
{id:"TIU-1704", q:"A, Z, B, Y, C, ....", opts:["W","V","X","Y","Z"], a:2, ex:"Dua sub-deret berselang: posisi ganjil A, B, C, ... (abjad maju); posisi genap Z, Y, ... (abjad mundur). Setelah C (maju), giliran mundur: Y − 1 = X."},
{id:"TIU-1705", q:"Seorang peternak lebah memanen madu dari tiga sarangnya berturut-turut sebanyak 48 liter, 60 liter, dan 72 liter. Seluruh madu akan dikemas ke dalam botol-botol berukuran sama sebesar mungkin tanpa sisa. Volume setiap botol adalah ....", opts:["12 liter","10 liter","8 liter","6 liter","16 liter"], a:0, ex:"Mencari FPB dari 48, 60, dan 72. 48 = 2^4 x 3, 60 = 2^2 x 3 x 5, 72 = 2^3 x 3^2. FPB = 2^2 x 3 = 12 liter."},
{id:"TIU-1706", q:"Tiga mesin cetak di sebuah percetakan memerlukan perawatan berkala masing-masing setiap 36 hari, 45 hari, dan 60 hari. Jika ketiga mesin dirawat bersama pada tanggal 1 Maret, ketiga mesin akan dirawat bersama lagi setelah ....", opts:["120 hari","180 hari","150 hari","240 hari","90 hari"], a:1, ex:"Mencari KPK dari 36, 45, dan 60. 36 = 2^2 x 3^2, 45 = 3^2 x 5, 60 = 2^2 x 3 x 5. KPK = 2^2 x 3^2 x 5 = 180 hari."},
{id:"TIU-1707", q:"Umur seorang pengrajin gerabah 3 tahun lebih tua daripada umur adiknya. Lima tahun yang lalu jumlah umur mereka adalah 47 tahun. Umur pengrajin tersebut sekarang adalah ....", opts:["27 tahun","29 tahun","30 tahun","31 tahun","33 tahun"], a:2, ex:"Jumlah umur sekarang = 47 + (2 x 5) = 57 tahun. Selisih umur 3 tahun, maka umur kakak = (57 + 3) : 2 = 30 tahun."},
{id:"TIU-1708", q:"Seorang penjahit membeli 3 kodi kancing baju seharga Rp90.000,00. Seluruh kancing dijual kembali dengan harga Rp1.800,00 per buah. Persentase keuntungan yang diperoleh adalah ....", opts:["15%","18%","22%","20%","25%"], a:3, ex:"3 kodi = 3 x 20 = 60 buah. Hasil penjualan = 60 x Rp1.800,00 = Rp108.000,00. Untung = Rp108.000,00 - Rp90.000,00 = Rp18.000,00. Persentase = Rp18.000,00/Rp90.000,00 x 100% = 20%."},
{id:"TIU-1709", q:"Seorang tengkulak mencampur 3 kg kopi arabika seharga Rp145.000,00 per kg dengan 2 kg kopi robusta seharga Rp95.000,00 per kg. Harga 1 kg kopi campuran tersebut adalah ....", opts:["Rp115.000,00","Rp120.000,00","Rp110.000,00","Rp130.000,00","Rp125.000,00"], a:4, ex:"(3 x Rp145.000,00 + 2 x Rp95.000,00) : 5 = (Rp435.000,00 + Rp190.000,00) : 5 = Rp625.000,00 : 5 = Rp125.000,00."},
{id:"TIU-1710", q:"Sebuah bus berangkat dari terminal pukul 06.15 menuju kota yang berjarak 132 km dengan kecepatan rata-rata 48 km/jam. Bus tersebut tiba di kota tujuan pukul ....", opts:["09.00","08.45","09.15","09.30","08.30"], a:0, ex:"Waktu tempuh = 132 : 48 = 2,75 jam = 2 jam 45 menit. 06.15 + 2 jam 45 menit = 09.00."},
{id:"TIU-1711", q:"Sebuah kolam pembesaran ikan lele berbentuk balok berukuran panjang 8 m, lebar 5 m, dan tinggi 1,2 m. Jika kolam diisi air hingga penuh, volume air di dalamnya adalah ....", opts:["42 m3","48 m3","45 m3","54 m3","40 m3"], a:1, ex:"Volume balok = 8 x 5 x 1,2 = 48 m3."},
{id:"TIU-1712", q:"Kelompok tani A beranggotakan 20 orang dengan rata-rata hasil panen 75 kg per orang, sedangkan kelompok tani B beranggotakan 30 orang dengan rata-rata hasil panen 85 kg per orang. Rata-rata hasil panen gabungan kedua kelompok adalah ....", opts:["80 kg","79 kg","81 kg","82 kg","80,5 kg"], a:2, ex:"(20 x 75 + 30 x 85) : 50 = (1.500 + 2.550) : 50 = 4.050 : 50 = 81 kg."},
{id:"TIU-1713", q:"Seorang petani memanen kopi dari kebunnya. Pada hari pertama ia memanen 2/3 bagian kebun dan pada hari kedua 1/6 bagian kebun. Bagian kebun yang belum dipanen adalah ....", opts:["1/3","1/4","1/5","1/6","1/2"], a:3, ex:"Bagian yang sudah dipanen = 2/3 + 1/6 = 4/6 + 1/6 = 5/6. Sisa = 1 - 5/6 = 1/6."},
{id:"TIU-1714", q:"Sebuah percetakan membeli 2,5 gros pensil warna. Seluruh pensil akan dikemas ulang ke dalam kotak-kotak yang masing-masing berisi 1 lusin. Banyak kotak yang dibutuhkan adalah ....", opts:["28 kotak","32 kotak","36 kotak","24 kotak","30 kotak"], a:4, ex:"2,5 gros = 2,5 x 144 = 360 buah. 360 : 12 = 30 kotak."},
{id:"TIU-1715", q:"Denah kebun vanili digambar dengan skala 1 : 1.500. Jika panjang kebun pada denah 14 cm, panjang kebun sebenarnya adalah ....", opts:["210 m","180 m","150 m","240 m","175 m"], a:0, ex:"Panjang sebenarnya = 14 x 1.500 = 21.000 cm = 210 m."},
{id:"TIU-1716", q:"Tiga mitra usaha warung kopi membagi keuntungan dengan perbandingan A : B = 5 : 6 dan B : C = 8 : 9. Jika mitra A menerima Rp4.000.000,00, bagian yang diterima mitra C adalah ....", opts:["Rp5.200.000,00","Rp5.400.000,00","Rp5.000.000,00","Rp4.800.000,00","Rp6.000.000,00"], a:1, ex:"A : B = 5 : 6 dan B : C = 8 : 9. Samakan B dengan KPK 6 dan 8 = 24, sehingga A : B : C = 20 : 24 : 27. Bagian A = 20 satuan = Rp4.000.000,00, maka 1 satuan = Rp200.000,00. Bagian C = 27 x Rp200.000,00 = Rp5.400.000,00."},
{id:"TIU-1717", q:"Seorang petani meminjam modal Rp3.600.000,00 ke koperasi dengan bunga 1,5% per bulan. Jika pinjaman dilunasi setelah 8 bulan, besar bunga yang harus dibayar adalah ....", opts:["Rp324.000,00","Rp378.000,00","Rp432.000,00","Rp486.000,00","Rp540.000,00"], a:2, ex:"Bunga = Rp3.600.000,00 x 1,5% x 8 = Rp3.600.000,00 x 0,12 = Rp432.000,00."},
{id:"TIU-1718", q:"Seorang kurir mengantar pesanan sejauh 36 km dengan kecepatan rata-rata 45 km/jam. Ia berangkat pukul 07.20 dan beristirahat 10 menit di tengah perjalanan. Kurir tiba di tempat tujuan pukul ....", opts:["08.08","08.28","08.10","08.18","08.38"], a:3, ex:"Waktu tempuh = 36 : 45 = 0,8 jam = 48 menit. 07.20 + 48 menit + 10 menit = 08.18."},
{id:"TIU-1719", q:"Sebuah bak penampung susu di peternakan sapi berbentuk balok berukuran 120 cm x 60 cm x 50 cm. Bak tersebut diisi susu sebanyak 3/4 bagian. Volume susu dalam bak adalah ....", opts:["240 liter","250 liter","300 liter","225 liter","270 liter"], a:4, ex:"Volume bak = 120 x 60 x 50 = 360.000 cm3 = 360 liter. Isi susu = 3/4 x 360 = 270 liter."},
{id:"TIU-1720", q:"Umur seorang ibu 3 kali umur anaknya. Dua belas tahun yang lalu jumlah umur mereka adalah 44 tahun. Umur anak tersebut sekarang adalah ....", opts:["17 tahun","15 tahun","19 tahun","14 tahun","21 tahun"], a:0, ex:"Jumlah umur sekarang = 44 + (2 x 12) = 68 tahun. Misal umur anak = x, maka 3x + x = 68, sehingga x = 17 tahun."},
{id:"TIU-1721", q:"Seorang pedagang membeli 150 kg beras seharga Rp1.800.000,00. Seluruh beras dijual dengan harga Rp13.500,00 per kg. Persentase keuntungan yang diperoleh pedagang adalah ....", opts:["10%","12,5%","15%","11,5%","12%"], a:1, ex:"Hasil penjualan = 150 x Rp13.500,00 = Rp2.025.000,00. Untung = Rp2.025.000,00 - Rp1.800.000,00 = Rp225.000,00. Persentase = Rp225.000,00/Rp1.800.000,00 x 100% = 12,5%."},
{id:"TIU-1722", q:"Seorang petani mencampur 40 kg pupuk A seharga Rp12.500,00 per kg dengan 60 kg pupuk B seharga Rp8.000,00 per kg. Harga rata-rata 1 kg pupuk campuran adalah ....", opts:["Rp9.500,00","Rp10.000,00","Rp9.800,00","Rp10.250,00","Rp9.000,00"], a:2, ex:"(40 x Rp12.500,00 + 60 x Rp8.000,00) : 100 = (Rp500.000,00 + Rp480.000,00) : 100 = Rp980.000,00 : 100 = Rp9.800,00."},
{id:"TIU-1723", q:"Tiga pompa air di sebuah tambak menyala bergantian masing-masing setiap 24 menit, 36 menit, dan 48 menit. Jika ketiga pompa menyala bersama pada pukul 08.00, ketiga pompa akan menyala bersama lagi pada pukul ....", opts:["10.00","10.12","11.24","10.24","11.00"], a:3, ex:"Mencari KPK dari 24, 36, dan 48. 24 = 2^3 x 3, 36 = 2^2 x 3^2, 48 = 2^4 x 3. KPK = 2^4 x 3^2 = 144 menit = 2 jam 24 menit. 08.00 + 2 jam 24 menit = 10.24."},
{id:"TIU-1724", q:"Di sebuah pabrik krupuk terdapat 8 karyawan pria dengan rata-rata berat badan 68,5 kg dan 12 karyawan wanita dengan rata-rata berat badan 52,5 kg. Rata-rata berat badan seluruh karyawan adalah ....", opts:["60,5 kg","61 kg","59,5 kg","60 kg","58,9 kg"], a:4, ex:"(8 x 68,5 + 12 x 52,5) : 20 = (548 + 630) : 20 = 1.178 : 20 = 58,9 kg."},
{id:"TIU-1725", q:"Denah sebuah gudang penyimpanan kopi digambar dengan skala 1 : 200. Panjang gudang pada denah 35 cm dan lebarnya 20 cm. Luas gudang sebenarnya adalah ....", opts:["2.800 m2","2.600 m2","3.000 m2","2.400 m2","2.500 m2"], a:0, ex:"Panjang sebenarnya = 35 x 200 = 7.000 cm = 70 m. Lebar sebenarnya = 20 x 200 = 4.000 cm = 40 m. Luas = 70 x 40 = 2.800 m2."},
{id:"TIU-1726", q:"Upah tiga buruh panen kopi berbanding Rina : Sinta = 4 : 5 dan Sinta : Tono = 6 : 7. Jika selisih upah Rina dan Tono Rp66.000,00, upah Sinta adalah ....", opts:["Rp150.000,00","Rp180.000,00","Rp168.000,00","Rp192.000,00","Rp144.000,00"], a:1, ex:"Samakan Sinta dengan KPK 5 dan 6 = 30, sehingga Rina : Sinta : Tono = 24 : 30 : 35. Selisih Rina dan Tono = 35 - 24 = 11 satuan = Rp66.000,00, maka 1 satuan = Rp6.000,00. Upah Sinta = 30 x Rp6.000,00 = Rp180.000,00."},
{id:"TIU-1727", q:"Seorang anggota koperasi menabung Rp4.500.000,00 dengan bunga 8% per tahun. Jika tabungan diambil setelah 15 bulan, jumlah tabungan yang diterima adalah ....", opts:["Rp4.850.000,00","Rp4.900.000,00","Rp4.950.000,00","Rp5.000.000,00","Rp5.040.000,00"], a:2, ex:"Bunga 15 bulan = Rp4.500.000,00 x 8% x 15/12 = Rp4.500.000,00 x 0,1 = Rp450.000,00. Jumlah tabungan = Rp4.500.000,00 + Rp450.000,00 = Rp4.950.000,00."},
{id:"TIU-1728", q:"Sebuah toko oleh-oleh memiliki 96 bungkus keripik, 120 botol sambal, dan 144 bungkus kopi bubuk. Ketiganya akan dibuat menjadi parsel-parsel dengan isi yang sama banyak. Jumlah parsel terbanyak yang dapat dibuat adalah ....", opts:["18 parsel","20 parsel","22 parsel","24 parsel","16 parsel"], a:3, ex:"Mencari FPB dari 96, 120, dan 144. 96 = 2^5 x 3, 120 = 2^3 x 3 x 5, 144 = 2^4 x 3^2. FPB = 2^3 x 3 = 24 parsel."},
{id:"TIU-1729", q:"Sebuah kereta berangkat dari stasiun pukul 08.40 dan tiba di stasiun tujuan pukul 11.10. Jika jarak kedua stasiun 150 km, kecepatan rata-rata kereta adalah ....", opts:["55 km/jam","58 km/jam","62 km/jam","65 km/jam","60 km/jam"], a:4, ex:"Waktu tempuh = 11.10 - 08.40 = 2 jam 30 menit = 2,5 jam. Kecepatan = 150 : 2,5 = 60 km/jam."},
{id:"TIU-1730", q:"Sebuah kebun bunga berbentuk lingkaran berdiameter 28 m akan dipagari sekelilingnya. Jika biaya pemasangan pagar Rp75.000,00 per meter, total biaya yang dibutuhkan adalah .... (pi = 22/7)", opts:["Rp6.600.000,00","Rp6.160.000,00","Rp6.480.000,00","Rp6.930.000,00","Rp6.300.000,00"], a:0, ex:"Keliling lingkaran = pi x d = 22/7 x 28 = 88 m. Biaya = 88 x Rp75.000,00 = Rp6.600.000,00."},
{id:"TIU-1731", q:"Sebuah toko elektronik menjual televisi seharga Rp480.000,00 dengan diskon 20%, kemudian pembeli mendapat tambahan diskon 10% dari harga setelah diskon pertama. Harga yang harus dibayar pembeli adalah ....", opts:["Rp345.600,00","Rp336.000,00","Rp364.800,00","Rp384.000,00","Rp408.000,00"], a:0, ex:"Rp480.000,00 × 0,8 = Rp384.000,00; Rp384.000,00 × 0,9 = Rp345.600,00."},
{id:"TIU-1732", q:"Harga selembar kain batik semula Rp200.000,00. Harga tersebut naik 20%, kemudian turun 25%. Persentase perubahan harga akhir dibandingkan harga semula adalah ....", opts:["Naik 10%","Turun 10%","Turun 5%","Naik 5%","Tetap"], a:1, ex:"Rp200.000,00 × 1,2 = Rp240.000,00; Rp240.000,00 × 0,75 = Rp180.000,00. Selisih Rp20.000,00 ÷ Rp200.000,00 = 10%, jadi turun 10%."},
{id:"TIU-1733", q:"Tiga orang bermitra dengan perbandingan modal 2 : 3 : 5. Jika laba usaha sebesar Rp4.200.000,00, selisih bagian laba pemilik modal terbesar dan terkecil adalah ....", opts:["Rp840.000,00","Rp1.050.000,00","Rp1.260.000,00","Rp1.680.000,00","Rp2.100.000,00"], a:2, ex:"Selisih perbandingan = 5 − 2 = 3; total = 10. 3/10 × Rp4.200.000,00 = Rp1.260.000,00."},
{id:"TIU-1734", q:"Sebuah proyek bendungan dapat diselesaikan oleh 12 pekerja dalam 20 hari. Setelah berjalan 8 hari, 4 pekerja dipindahkan ke proyek lain. Pekerjaan tersebut akan selesai dalam waktu ....", opts:["12 hari","14 hari","16 hari","18 hari","24 hari"], a:3, ex:"Total usaha = 12 × 20 = 240 orang-hari. Sudah dikerjakan 12 × 8 = 96, sisa 144. Dengan 8 pekerja: 144 ÷ 8 = 18 hari lagi."},
{id:"TIU-1735", q:"Sebuah mobil berangkat dari kota M menuju kota N dengan kecepatan 60 km/jam, dan pada saat yang sama sebuah bus berangkat dari kota N menuju kota M dengan kecepatan 40 km/jam. Jika jarak kedua kota 250 km, kedua kendaraan berpapasan setelah ....", opts:["1 jam 30 menit","2 jam","2 jam 15 menit","2 jam 45 menit","2 jam 30 menit"], a:4, ex:"Kecepatan relatif = 60 + 40 = 100 km/jam. Waktu = 250 ÷ 100 = 2,5 jam = 2 jam 30 menit."},
{id:"TIU-1736", q:"Sebuah keran mengalirkan air dengan debit 2,4 liter/detik ke dalam sebuah bak berkapasitas 720 liter yang kosong. Waktu yang diperlukan hingga bak penuh adalah ....", opts:["5 menit","4 menit 30 detik","6 menit","7 menit 30 detik","4 menit"], a:0, ex:"720 ÷ 2,4 = 300 detik = 5 menit."},
{id:"TIU-1737", q:"Di sebuah pabrik tahu terdapat 60 karyawan. Sebanyak 25% di antaranya adalah manajer dan sisanya staf, sedangkan 1/3 dari jumlah staf adalah perempuan. Banyak staf laki-laki adalah ....", opts:["20 orang","25 orang","30 orang","35 orang","40 orang"], a:2, ex:"Staf = 75% × 60 = 45 orang. Staf laki-laki = 2/3 × 45 = 30 orang."},
{id:"TIU-1738", q:"Sebuah denah ruko digambar dengan skala 1 : 250. Jika panjang ruko pada denah 14 cm, panjang ruko sebenarnya adalah ....", opts:["28 m","32 m","30 m","35 m","40 m"], a:3, ex:"14 × 250 = 3.500 cm = 35 m."},
{id:"TIU-1739", q:"Seorang wiraniaga pupuk menerima gaji pokok Rp3.000.000,00 ditambah komisi 4% dari total penjualan. Jika dalam sebulan ia menjual pupuk senilai Rp45.000.000,00, penghasilan yang diterimanya adalah ....", opts:["Rp4.200.000,00","Rp4.500.000,00","Rp4.600.000,00","Rp4.750.000,00","Rp4.800.000,00"], a:4, ex:"Komisi = 4/100 × Rp45.000.000,00 = Rp1.800.000,00. Total = Rp3.000.000,00 + Rp1.800.000,00 = Rp4.800.000,00."},
{id:"TIU-1740", q:"Seorang pengusaha konveksi membeli mesin obras seharga Rp750.000,00, kemudian menjualnya kembali seharga Rp690.000,00. Persentase kerugian yang dialami adalah ....", opts:["6%","8%","10%","12%","15%"], a:1, ex:"Rugi = Rp750.000,00 − Rp690.000,00 = Rp60.000,00. 60.000 ÷ 750.000 = 8%."},
{id:"TIU-1741", q:"Kurir A berangkat pukul 07.00 dengan kecepatan 50 km/jam. Kurir B berangkat pukul 07.30 dari tempat dan rute yang sama dengan kecepatan 70 km/jam. Kurir B akan menyusul kurir A pada pukul ....", opts:["08.30","08.40","08.45","09.00","09.15"], a:2, ex:"Dalam 0,5 jam A menempuh 25 km. Waktu menyusul = 25 ÷ (70 − 50) = 1,25 jam = 1 jam 15 menit. 07.30 + 1:15 = 08.45."},
{id:"TIU-1742", q:"Persediaan pakan di sebuah peternakan cukup untuk 24 ekor ayam selama 30 hari. Jika 6 ekor ayam dijual, persediaan pakan tersebut cukup untuk ....", opts:["40 hari","36 hari","32 hari","28 hari","24 hari"], a:0, ex:"Perbandingan berbalik nilai: 24 × 30 ÷ 18 = 40 hari."},
{id:"TIU-1743", q:"Seorang sopir menempuh perjalanan pergi dengan kecepatan 60 km/jam dan pulang melalui rute yang sama dengan kecepatan 40 km/jam. Kecepatan rata-rata perjalanan pergi-pulang tersebut adalah ....", opts:["46 km/jam","48 km/jam","50 km/jam","52 km/jam","54 km/jam"], a:1, ex:"Rata-rata = 2 × 60 × 40 ÷ (60 + 40) = 4.800 ÷ 100 = 48 km/jam."},
{id:"TIU-1744", q:"Sebuah laptop dibanderol Rp1.250.000,00 dengan diskon 30% dan tambahan diskon 15% dari harga setelah diskon pertama. Harga yang harus dibayar adalah ....", opts:["Rp687.500,00","Rp718.750,00","Rp781.250,00","Rp743.750,00","Rp812.500,00"], a:3, ex:"Rp1.250.000,00 × 0,7 = Rp875.000,00; Rp875.000,00 × 0,85 = Rp743.750,00."},
{id:"TIU-1745", q:"Di sebuah koperasi, 5 kg gula pasir dijual seharga Rp67.500,00. Harga 8 kg gula pasir adalah ....", opts:["Rp94.500,00","Rp101.250,00","Rp105.000,00","Rp106.500,00","Rp108.000,00"], a:4, ex:"Harga per kg = Rp67.500,00 ÷ 5 = Rp13.500,00. 8 × Rp13.500,00 = Rp108.000,00."},
{id:"TIU-1746", q:"Setelah mendapat kenaikan gaji 10%, gaji seorang pegawai menjadi Rp5.500.000,00. Gaji pegawai tersebut sebelum kenaikan adalah ....", opts:["Rp5.000.000,00","Rp4.950.000,00","Rp5.050.000,00","Rp4.900.000,00","Rp5.100.000,00"], a:0, ex:"Rp5.500.000,00 ÷ 1,1 = Rp5.000.000,00."},
{id:"TIU-1747", q:"Seorang pedagang membagi modalnya Rp2.000.000,00 menjadi dua bagian: Rp1.200.000,00 yang menghasilkan keuntungan 20% dan Rp800.000,00 yang mengalami kerugian 10%. Persentase keuntungan bersih dari seluruh modal adalah ....", opts:["6%","8%","10%","4%","12%"], a:1, ex:"Hasil = Rp1.200.000,00 × 1,2 + Rp800.000,00 × 0,9 = Rp1.440.000,00 + Rp720.000,00 = Rp2.160.000,00. Untung Rp160.000,00 ÷ Rp2.000.000,00 = 8%."},
{id:"TIU-1748", q:"Sebuah kereta berangkat dari stasiun P pukul 08.00 dengan kecepatan 80 km/jam menuju stasiun Q. Kereta lain berangkat dari stasiun Q pukul 08.30 menuju stasiun P dengan kecepatan 70 km/jam. Jika jarak kedua stasiun 360 km, kedua kereta berpapasan pada pukul ....", opts:["10.30","10.32","10.38","10.40","10.45"], a:2, ex:"Pukul 08.30 kereta pertama telah menempuh 40 km, sisa 320 km. Waktu = 320 ÷ (80 + 70) = 2 jam 8 menit. 08.30 + 2:08 = 10.38."},
{id:"TIU-1749", q:"Keran A dapat mengisi sebuah kolam renang dalam 3 jam, sedangkan keran B dalam 6 jam. Jika kedua keran dibuka bersama-sama, kolam akan penuh dalam waktu ....", opts:["1 jam 30 menit","1 jam 45 menit","2 jam 15 menit","2 jam","2 jam 30 menit"], a:3, ex:"1 ÷ (1/3 + 1/6) = 1 ÷ 1/2 = 2 jam."},
{id:"TIU-1750", q:"Jarak antara dua desa pada peta adalah 15 cm. Jika jarak sebenarnya 45 km, skala peta tersebut adalah ....", opts:["1 : 250.000","1 : 350.000","1 : 200.000","1 : 400.000","1 : 300.000"], a:4, ex:"45 km = 4.500.000 cm. 4.500.000 ÷ 15 = 300.000, jadi skala 1 : 300.000."},
{id:"TIU-1751", q:"Semua arkeolog menyimpan catatan lapangan. Beberapa kurator museum adalah arkeolog. Kesimpulan yang tepat adalah ....", opts:["Beberapa kurator museum menyimpan catatan lapangan","Semua kurator museum menyimpan catatan lapangan","Semua arkeolog adalah kurator museum","Tidak ada kurator museum yang menyimpan catatan lapangan","Tidak dapat disimpulkan"], a:0, ex:"Silogisme Darii: premis mayor universal afirmatif (semua A adalah B) dan premis minor partikular afirmatif (beberapa C adalah A) menghasilkan kesimpulan partikular afirmatif yang valid: beberapa C adalah B."},
{id:"TIU-1752", q:"Jika pameran lukisan dibuka untuk umum, maka tiket daring tersedia. Ternyata pameran lukisan dibuka untuk umum. Kesimpulan yang tepat adalah ....", opts:["Tiket daring tidak tersedia","Tiket daring tersedia","Pameran lukisan tidak dibuka untuk umum","Tiket hanya tersedia di lokasi","Tidak dapat disimpulkan"], a:1, ex:"Modus ponens: dari 'jika P maka Q' dan 'P' disimpulkan 'Q' secara valid."},
{id:"TIU-1753", q:"Jika lampu mercusuar menyala, maka kapal-kapal dapat melihatnya dari laut. Ternyata kapal-kapal tidak dapat melihatnya dari laut. Kesimpulan yang tepat adalah ....", opts:["Lampu mercusuar menyala","Kapal-kapal terlalu jauh dari pantai","Lampu mercusuar tidak menyala","Cuaca sedang berkabut tebal","Tidak dapat disimpulkan"], a:2, ex:"Modus tollens: dari 'jika P maka Q' dan 'tidak Q' disimpulkan 'tidak P' secara valid."},
{id:"TIU-1754", q:"Jika mesin tenun beroperasi, maka terdengar bunyi berderak dari ruang produksi. Ternyata terdengar bunyi berderak dari ruang produksi. Kesimpulan yang tepat adalah ....", opts:["Mesin tenun sedang beroperasi","Ruang produksi sedang sepi","Bunyi berderak berasal dari mesin tenun","Tidak dapat disimpulkan","Mesin tenun tidak beroperasi"], a:3, ex:"Sesat pikir afirmasi konsekuen: dari 'jika P maka Q' dan 'Q' tidak dapat disimpulkan 'P', sebab Q dapat disebabkan oleh hal lain selain P."},
{id:"TIU-1755", q:"Pernyataan 'Semua penyelam mutiara memakai tabung oksigen' ternyata SALAH. Kesimpulan yang tepat adalah ....", opts:["Semua penyelam mutiara tidak memakai tabung oksigen","Tidak ada penyelam mutiara yang memakai tabung oksigen","Penyelam mutiara dilarang memakai tabung oksigen","Sebagian besar penyelam mutiara memakai tabung oksigen","Beberapa penyelam mutiara tidak memakai tabung oksigen"], a:4, ex:"Negasi dari 'semua A adalah B' adalah 'beberapa A bukan B'. Ingkaran kuantor universal menghasilkan pernyataan partikular negatif."},
{id:"TIU-1756", q:"Semua pembuat keris adalah pandai besi. Semua pandai besi menguasai teknik tempa. Semua yang menguasai teknik tempa bekerja dengan api. Kesimpulan yang tepat adalah ....", opts:["Semua pembuat keris bekerja dengan api","Semua yang bekerja dengan api adalah pembuat keris","Beberapa pandai besi bukan pembuat keris","Tidak ada pembuat keris yang bekerja dengan api","Tidak dapat disimpulkan"], a:0, ex:"Silogisme berantai (sorites): setiap suku tengah menghubungkan premis berikutnya sehingga 'semua pembuat keris' termasuk dalam kelompok 'yang bekerja dengan api'."},
{id:"TIU-1757", q:"Jika hujan turun, maka panggung pertunjukan wayang ditutup. Ternyata panggung pertunjukan wayang tidak ditutup. Kesimpulan yang tepat adalah ....", opts:["Hujan sedang turun","Hujan tidak turun","Pertunjukan wayang dibatalkan","Panggung rusak sehingga tidak bisa ditutup","Tidak dapat disimpulkan"], a:1, ex:"Kontraposisi: 'jika P maka Q' ekuivalen dengan 'jika tidak Q maka tidak P'. Panggung tidak ditutup berarti hujan tidak turun."},
{id:"TIU-1758", q:"Jika tungku peleburan dinyalakan, maka cerobong mengeluarkan asap. Ternyata tungku peleburan tidak dinyalakan. Kesimpulan yang tepat adalah ....", opts:["Cerobong tidak mengeluarkan asap","Tungku peleburan rusak","Tidak dapat disimpulkan","Cerobong mengeluarkan asap dari sumber lain","Asap berbahaya bagi pekerja"], a:2, ex:"Sesat pikir penyangkalan anteseden: dari 'jika P maka Q' dan 'tidak P' tidak dapat disimpulkan 'tidak Q', sebab Q dapat terjadi karena sebab lain."},
{id:"TIU-1759", q:"Pernyataan 'Beberapa kaktus saguaro tumbuh di rawa' ternyata SALAH. Kesimpulan yang tepat adalah ....", opts:["Beberapa kaktus saguaro tidak tumbuh di rawa","Semua kaktus saguaro tumbuh di rawa","Kaktus saguaro tidak dapat hidup di rawa","Semua kaktus saguaro tidak tumbuh di rawa","Tidak dapat disimpulkan"], a:3, ex:"Negasi dari 'beberapa A adalah B' adalah 'semua A bukan B'. Ingkaran kuantor partikular menghasilkan pernyataan universal negatif."},
{id:"TIU-1760", q:"Tukang kunci itu membawa kunci pas atau kunci inggris. Ternyata ia tidak membawa kunci pas. Kesimpulan yang tepat adalah ....", opts:["Ia tidak membawa kunci apa pun","Ia membawa kedua jenis kunci","Kunci pasnya tertinggal di bengkel","Tidak dapat disimpulkan","Ia membawa kunci inggris"], a:4, ex:"Silogisme disjungtif: dari 'P atau Q' dan 'tidak P' disimpulkan 'Q' secara valid."},
{id:"TIU-1761", q:"Penelitian menunjukkan semua atlet yang berlatih di dataran tinggi memiliki kapasitas paru-paru besar. Sinta memiliki kapasitas paru-paru besar. Kesimpulan yang tepat adalah ....", opts:["Tidak dapat disimpulkan bahwa Sinta berlatih di dataran tinggi","Sinta berlatih di dataran tinggi","Sinta adalah atlet profesional","Semua orang berkemampuan paru-paru besar adalah atlet","Sinta tidak berlatih di dataran tinggi"], a:0, ex:"Afirmasi konsekuen: kapasitas paru-paru besar adalah akibat yang dapat disebabkan banyak hal (genetik, cabang olahraga lain), sehingga sebabnya tidak dapat disimpulkan."},
{id:"TIU-1762", q:"Peserta dinyatakan lulus ujian praktik hanya jika ia menyelesaikan seluruh modul. Dimas telah menyelesaikan seluruh modul. Kesimpulan yang tepat adalah ....", opts:["Dimas pasti lulus ujian praktik","Dimas tidak lulus ujian praktik","Modul yang diselesaikan Dimas tidak valid","Tidak dapat disimpulkan apakah Dimas lulus","Dimas harus mengulang ujian praktik"], a:3, ex:"'A hanya jika B' berarti 'jika A maka B'. Diketahui B (menyelesaikan modul) benar, tetapi itu afirmasi konsekuen: B dapat benar tanpa A, misalnya nilai praktiknya kurang."},
{id:"TIU-1763", q:"Pengunjung boleh naik ke dek observasi hanya jika memakai gelang khusus. Rani naik ke dek observasi. Kesimpulan yang tepat adalah ....", opts:["Rani tidak memakai gelang khusus","Gelang khusus tidak diperlukan lagi","Rani memakai gelang khusus","Semua pengunjung memakai gelang khusus","Tidak dapat disimpulkan"], a:2, ex:"'A hanya jika B' berarti 'jika A maka B'. Diketahui A (Rani naik) benar, maka dengan modus ponens B (memakai gelang khusus) benar."},
{id:"TIU-1764", q:"Jika angin bertiup kencang dan layar terkembang, maka perahu melaju cepat. Ternyata angin bertiup kencang dan layar terkembang. Kesimpulan yang tepat adalah ....", opts:["Perahu melaju lambat","Layar perahu robek","Angin bertiup kencang tetapi layar tidak terkembang","Perahu melaju cepat","Tidak dapat disimpulkan"], a:3, ex:"Modus ponens dengan anteseden majemuk: anteseden '(P dan Q)' terpenuhi seluruhnya, maka konsekuen 'R' mengikuti secara valid."},
{id:"TIU-1765", q:"Jika nahkoda berpengalaman, maka pelayaran aman. Ternyata nahkoda tidak berpengalaman. Kesimpulan yang tepat adalah ....", opts:["Pelayaran tidak aman","Nahkoda harus diganti","Pelayaran aman karena cuaca baik","Nahkoda berpengalaman dalam bidang lain","Tidak dapat disimpulkan"], a:4, ex:"Penyangkalan anteseden: dari 'jika P maka Q' dan 'tidak P' tidak dapat disimpulkan 'tidak Q'; pelayaran dapat aman karena faktor lain."},
{id:"TIU-1766", q:"Jika embun turun, maka rumput menjadi basah. Jika rumput menjadi basah, maka siput keluar dari persembunyian. Ternyata embun turun. Kesimpulan yang tepat adalah ....", opts:["Siput keluar dari persembunyian","Rumput menjadi kering","Embun tidak turun","Siput tetap bersembunyi","Tidak dapat disimpulkan"], a:0, ex:"Silogisme hipotesis: 'jika P maka Q' dan 'jika Q maka R' menghasilkan 'jika P maka R'; dengan P benar, R mengikuti lewat modus ponens berantai."},
{id:"TIU-1767", q:"Jika mesin cetak berjalan, maka tinta mengalir. Jika tinta mengalir, maka kertas tercetak. Ternyata kertas tidak tercetak. Kesimpulan yang tepat adalah ....", opts:["Mesin cetak berjalan normal","Mesin cetak tidak berjalan","Tinta mengalir dengan lancar","Kertas tercetak sebagian","Tidak dapat disimpulkan"], a:1, ex:"Modus tollens berantai: 'tidak R' meniadakan 'Q' (tinta tidak mengalir), yang meniadakan 'P' (mesin cetak tidak berjalan)."},
{id:"TIU-1768", q:"Tidak ada lumba-lumba yang bernapas dengan insang. Paus orca bukan lumba-lumba. Kesimpulan yang tepat adalah ....", opts:["Paus orca bernapas dengan insang","Semua paus orca bernapas dengan paru-paru","Tidak dapat disimpulkan","Paus orca adalah lumba-lumba","Tidak ada paus orca yang bernapas"], a:2, ex:"Sesat pikir: premis 'tidak ada A adalah B' dan 'C bukan A' tidak menghubungkan C dengan B sama sekali; tidak ada kesimpulan valid yang dapat ditarik."},
{id:"TIU-1769", q:"Semua kolektor perangko menyimpan album khusus. Beberapa filatelis tidak menyimpan album khusus. Kesimpulan yang tepat adalah ....", opts:["Semua filatelis adalah kolektor perangko","Tidak ada filatelis yang menyimpan album khusus","Semua kolektor perangko adalah filatelis","Beberapa filatelis bukan kolektor perangko","Tidak dapat disimpulkan"], a:3, ex:"Silogisme Baroco: premis mayor universal afirmatif dan minor partikular negatif menghasilkan kesimpulan partikular negatif yang valid."},
{id:"TIU-1770", q:"Jika pagi cerah, maka nelayan melaut. Jika angin sepoi-sepoi, maka petani menjemur padi. Ternyata pagi cerah atau angin sepoi-sepoi. Kesimpulan yang tepat adalah ....", opts:["Nelayan melaut dan petani menjemur padi","Cuaca tidak menentu","Nelayan tidak melaut","Tidak dapat disimpulkan","Nelayan melaut atau petani menjemur padi"], a:4, ex:"Dilema konstruktif: dari dua implikasi dan disjungsi antesedennya, disimpulkan disjungsi konsekuennya secara valid."},
{id:"TIU-1771", q:"Tidak benar bahwa Rian pandai memanah dan pandai berkuda. Diketahui Rian pandai memanah. Kesimpulan yang tepat adalah ....", opts:["Rian tidak pandai berkuda","Rian tidak pandai memanah","Rian pandai dalam semua olahraga","Rian tidak pandai memanah maupun berkuda","Tidak dapat disimpulkan"], a:0, ex:"Negasi konjungsi (De Morgan): 'tidak (P dan Q)' ekuivalen dengan 'tidak P atau tidak Q'; karena P benar, maka yang berlaku adalah 'tidak Q'."},
{id:"TIU-1772", q:"Tiket pertunjukan tersedia secara daring atau luring. Ternyata tiket daring telah habis. Kesimpulan yang tepat adalah ....", opts:["Pertunjukan dibatalkan","Tiket tersedia secara luring","Tiket daring masih tersedia","Penonton harus pulang","Tidak dapat disimpulkan"], a:1, ex:"Silogisme disjungtif: dari 'P atau Q' dan 'tidak P' disimpulkan 'Q' secara valid."},
{id:"TIU-1773", q:"Jika tanaman disiram teratur, maka ia tumbuh subur. Ternyata tanaman itu tumbuh subur. Kesimpulan yang tepat adalah ....", opts:["Tanaman itu disiram teratur","Tanaman itu tidak disiram teratur","Tidak dapat disimpulkan","Tanaman itu layu","Penyiraman tidak berpengaruh"], a:2, ex:"Sesat pikir afirmasi konsekuen (konvers): tumbuh subur dapat disebabkan pupuk, cahaya, atau tanah yang baik, bukan semata penyiraman teratur."},
{id:"TIU-1774", q:"Semua kartografer menggambar peta. Semua yang menggambar peta memahami skala. Beberapa kartografer bekerja di dinas tata ruang. Kesimpulan yang tepat adalah ....", opts:["Semua yang bekerja di dinas tata ruang adalah kartografer","Tidak ada kartografer yang memahami skala","Semua yang memahami skala bekerja di dinas tata ruang","Beberapa yang bekerja di dinas tata ruang memahami skala","Tidak dapat disimpulkan"], a:3, ex:"Silogisme berantai: 'beberapa kartografer' termasuk dalam 'penggambar peta' yang semuanya 'memahami skala', sehingga kesimpulan partikularnya valid."},
{id:"TIU-1775", q:"Jika panel surya bersih dan cuaca cerah, maka daya yang dihasilkan maksimal. Ternyata panel surya kotor. Kesimpulan yang tepat adalah ....", opts:["Daya yang dihasilkan tidak maksimal","Cuaca sedang mendung","Panel surya harus diganti","Daya yang dihasilkan tetap maksimal","Tidak dapat disimpulkan"], a:4, ex:"Penyangkalan sebagian anteseden: anteseden '(P dan Q)' tidak terpenuhi, tetapi dari 'jika (P dan Q) maka R' dan 'tidak P' tidak dapat disimpulkan 'tidak R'."},
{id:"TIU-1776", q:"Lampu indikator menyala jika dan hanya jika mesin terlalu panas. Ternyata mesin tidak terlalu panas. Kesimpulan yang tepat adalah ....", opts:["Lampu indikator tidak menyala","Lampu indikator menyala","Mesin terlalu panas","Lampu indikator rusak","Tidak dapat disimpulkan"], a:0, ex:"Ekuivalensi 'P jika dan hanya jika Q' berarti 'jika Q maka P' sekaligus 'jika P maka Q'; dari 'tidak Q' disimpulkan 'tidak P' lewat modus tollens."},
{id:"TIU-1777", q:"Beberapa apoteker meracik jamu tradisional. Beberapa peracik jamu tradisional adalah herbalis. Kesimpulan yang tepat adalah ....", opts:["Beberapa apoteker adalah herbalis","Tidak dapat disimpulkan","Semua apoteker adalah herbalis","Tidak ada apoteker yang meracik jamu tradisional","Semua herbalis adalah apoteker"], a:1, ex:"Dua premis partikular tidak menghasilkan kesimpulan valid: suku tengah 'peracik jamu tradisional' tidak terdistribusi sehingga kedua kelompok 'beberapa' itu belum tentu bertaut."},
{id:"TIU-1778", q:"Wisatawan boleh masuk ke dalam gua hanya jika memakai helm pelindung. Ternyata seorang wisatawan tidak memakai helm pelindung. Kesimpulan yang tepat adalah ....", opts:["Wisatawan itu boleh masuk ke dalam gua","Helm pelindung tidak tersedia","Wisatawan itu tidak boleh masuk ke dalam gua","Gua ditutup untuk umum","Tidak dapat disimpulkan"], a:2, ex:"'A hanya jika B' berarti 'jika A maka B'; dari 'tidak B' disimpulkan 'tidak A' lewat modus tollens secara valid."},
{id:"TIU-1779", q:"Setiap peningkatan suhu mesin selalu didahului oleh bunyi dengung. Ternyata terdengar bunyi dengung dari ruang mesin. Kesimpulan yang tepat adalah ....", opts:["Suhu mesin pasti meningkat","Tidak dapat disimpulkan bahwa suhu mesin meningkat","Bunyi dengung disebabkan oleh suhu mesin","Mesin harus segera dimatikan","Suhu mesin tidak meningkat"], a:1, ex:"Bunyi dengung adalah syarat perlu, bukan syarat cukup, bagi peningkatan suhu: setiap kenaikan suhu didahului dengung, tetapi dengung dapat muncul tanpa kenaikan suhu."},
{id:"TIU-1780", q:"Jika ketua panitia hadir atau surat kuasa diterima, maka rapat dinyatakan sah. Ternyata ketua panitia tidak hadir dan surat kuasa tidak diterima. Kesimpulan yang tepat adalah ....", opts:["Rapat dinyatakan sah","Rapat ditunda keesokan harinya","Ketua panitia mengirim surat kuasa","Tidak dapat disimpulkan","Rapat tidak dinyatakan sah"], a:4, ex:"Dari 'tidak P dan tidak Q' diperoleh 'tidak (P atau Q)' (De Morgan); dengan modus tollens atas 'jika (P atau Q) maka R', disimpulkan 'tidak R' secara valid."},
{id:"TIU-1781", q:"Gambar ke-1 memuat 1 lingkaran, gambar ke-2 memuat 3 lingkaran, gambar ke-3 memuat 5 lingkaran, dan gambar ke-4 memuat 7 lingkaran. Banyak lingkaran pada gambar ke-5 adalah ....", opts:["7","8","10","9","11"], a:3, ex:"Pola +2: 1, 3, 5, 7, 9."},
{id:"TIU-1782", q:"Gambar ke-1 memuat sebuah panah yang menunjuk ke atas. Setiap gambar berikutnya merupakan hasil putaran 90° searah jarum jam dari gambar sebelumnya. Arah panah pada gambar ke-4 adalah ....", opts:["Ke kiri","Ke kanan","Ke bawah","Ke atas","Serong ke kiri atas"], a:0, ex:"Atas → kanan → bawah → kiri (putar 90° searah jarum jam tiap langkah)."},
{id:"TIU-1783", q:"Gambar ke-1 memuat trapesium, gambar ke-2 memuat jajar genjang, gambar ke-3 memuat trapesium, gambar ke-4 memuat jajar genjang, dan seterusnya berselang-seling. Bangun pada gambar ke-9 adalah ....", opts:["Jajar genjang","Belah ketupat","Layang-layang","Persegi","Trapesium"], a:4, ex:"Pola selang-seling: gambar ganjil = trapesium, gambar genap = jajar genjang. Gambar ke-9 (ganjil) = trapesium."},
{id:"TIU-1784", q:"Pada sebuah dadu, jumlah mata pada sisi-sisi yang berhadapan selalu 7. Jika sisi atas dadu bermata 2 dan sisi depan bermata 5, mata dadu pada sisi bawah adalah ....", opts:["2","5","3","4","6"], a:1, ex:"Sisi atas berhadapan dengan sisi bawah, sehingga 2 + bawah = 7, jadi sisi bawah = 5."},
{id:"TIU-1785", q:"Selembar kertas berbentuk persegi dilipat menjadi dua bagian yang sama besar, kemudian dilubangi satu kali tepat di tengah bagian kertas yang terlipat. Setelah kertas dibuka kembali, banyak lubang pada kertas adalah ....", opts:["1","3","2","4","5"], a:2, ex:"Satu lubang menembus 2 lapis lipatan, sehingga setelah dibuka terdapat 2 lubang."},
{id:"TIU-1786", q:"Gambar ke-1 memuat segitiga dengan bilangan 2, 3, dan 5 pada ketiga titik sudutnya serta bilangan 20 di tengahnya. Gambar ke-2 memuat segitiga dengan bilangan 1, 4, dan 6 pada titik sudutnya serta bilangan 22 di tengahnya. Gambar ke-3 memuat segitiga dengan bilangan 3, 3, dan 7 pada titik sudutnya. Bilangan di tengah gambar ke-3 adalah ....", opts:["26","24","25","27","28"], a:0, ex:"Tengah = (jumlah ketiga sudut) × 2: (2+3+5)×2=20, (1+4+6)×2=22, (3+3+7)×2=26."},
{id:"TIU-1787", q:"Gambar ke-1 memuat bintang kecil berwarna kuning. Gambar ke-2 memuat segi delapan besar berwarna hijau. Gambar ke-3 memuat bintang kecil berwarna kuning. Gambar ke-4 memuat segi delapan besar berwarna hijau, dan seterusnya berselang-seling. Gambar ke-10 adalah ....", opts:["Bintang kecil berwarna kuning","Bintang besar berwarna kuning","Segi delapan kecil berwarna hijau","Segi delapan besar berwarna hijau","Segi delapan besar berwarna kuning"], a:3, ex:"Pola selang-seling dua gambar: ganjil = bintang kecil kuning, genap = segi delapan besar hijau. Gambar ke-10 (genap) = segi delapan besar berwarna hijau."},
{id:"TIU-1788", q:"Gambar ke-1 memuat segitiga, gambar ke-2 memuat segiempat, gambar ke-3 memuat segilima, dan gambar ke-4 memuat segienam. Bangun pada gambar ke-5 adalah ....", opts:["Segienam","Segitujuh","Segidelapan","Segisembilan","Segisepuluh"], a:1, ex:"Jumlah sisi bertambah 1 tiap gambar: 3, 4, 5, 6, 7. Gambar ke-5 = segitujuh."},
{id:"TIU-1789", q:"Bangun datar berikut yang tidak memiliki simetri lipat adalah ....", opts:["Belah ketupat","Layang-layang","Segitiga sama sisi","Persegi","Jajar genjang"], a:4, ex:"Belah ketupat, layang-layang, segitiga sama sisi, dan persegi memiliki simetri lipat, sedangkan jajar genjang (umum) tidak memilikinya."},
{id:"TIU-1790", q:"Gambar ke-1 memuat huruf 'p' yang diputar 180° sehingga terbaca 'd'. Gambar ke-2 memuat huruf 'd' yang diputar 180° sehingga terbaca 'p'. Gambar ke-3 memuat huruf 'p' yang diputar 180° lagi, dan seterusnya berselang-seling. Huruf yang terbaca pada gambar ke-7 adalah ....", opts:["p","q","d","b","u"], a:2, ex:"Putaran 180° membuat 'p' ↔ 'd' berselang-seling. Gambar ganjil terbaca 'd', sehingga gambar ke-7 = 'd'."},
{id:"TIU-1791", q:"Gambar ke-1 memuat 2 gambar hati, gambar ke-2 memuat 4 gambar hati, gambar ke-3 memuat 7 gambar hati, dan gambar ke-4 memuat 11 gambar hati. Banyak gambar hati pada gambar ke-5 adalah ....", opts:["14","15","13","16","17"], a:3, ex:"Selisih bertambah 1: +2, +3, +4, +5. 11 + 5 = 16."},
{id:"TIU-1792", q:"Pada sebuah dadu standar, jumlah mata pada sisi-sisi yang berhadapan selalu 7. Jika mata dadu pada sisi atas adalah 4 dan pada sisi depan adalah 3, mata dadu pada sisi belakang adalah ....", opts:["4","2","3","5","6"], a:0, ex:"Sisi depan berhadapan dengan sisi belakang, sehingga 3 + belakang = 7, jadi sisi belakang = 4."},
{id:"TIU-1793", q:"Selembar kertas berbentuk lingkaran dilipat menjadi setengah lingkaran, kemudian dilipat sekali lagi menjadi seperempat lingkaran. Setelah itu, kertas yang terlipat digunting kecil tepat di tengah busurnya. Setelah kertas dibuka kembali, banyak lubang pada kertas adalah ....", opts:["2","4","3","6","8"], a:1, ex:"Kertas terlipat menjadi 4 lapis, satu guntingan menembus keempatnya, sehingga setelah dibuka terdapat 4 lubang."},
{id:"TIU-1794", q:"Gambar ke-1 memuat persegi dengan bilangan 2, 3, 4, dan 5 pada keempat titik sudutnya serta bilangan 54 di tengahnya. Gambar ke-2 memuat persegi dengan bilangan 1, 2, 3, dan 4 pada titik sudutnya serta bilangan 30 di tengahnya. Gambar ke-3 memuat persegi dengan bilangan 3, 3, 2, dan 4 pada titik sudutnya. Bilangan di tengah gambar ke-3 adalah ....", opts:["36","37","39","40","38"], a:4, ex:"Tengah = jumlah kuadrat keempat sudut: 2²+3²+4²+5²=54, 1²+2²+3²+4²=30, 3²+3²+2²+4²=38."},
{id:"TIU-1795", q:"Setiap gambar merupakan hasil pencerminan gambar sebelumnya terhadap garis vertikal. Gambar ke-1 memuat huruf 'R'. Gambar yang sama dengan gambar ke-2 adalah gambar ke- ....", opts:["1","4","3","5","Tidak ada"], a:1, ex:"Dua kali pencerminan mengembalikan ke bentuk semula: gambar ke-1 = ke-3 = ke-5 ('R'), gambar ke-2 = ke-4 (bayangan cermin 'R')."},
{id:"TIU-1796", q:"Gambar ke-1 memuat lingkaran yang di dalamnya terdapat satu titik hitam. Gambar ke-2 memuat belah ketupat yang di dalamnya terdapat satu titik putih. Gambar ke-3 memuat lingkaran yang di dalamnya terdapat satu titik hitam, dan seterusnya berselang-seling. Gambar ke-9 adalah ....", opts:["Lingkaran berisi satu titik putih","Belah ketupat berisi satu titik hitam","Belah ketupat berisi satu titik putih","Lingkaran berisi satu titik hitam","Lingkaran berisi dua titik hitam"], a:3, ex:"Pola selang-seling: gambar ganjil = lingkaran berisi titik hitam. Gambar ke-9 (ganjil) = lingkaran berisi satu titik hitam."},
{id:"TIU-1797", q:"Gambar ke-1 memuat segi enam, gambar ke-2 memuat segi delapan, dan gambar ke-3 memuat segi sepuluh. Banyak titik sudut bangun pada gambar ke-4 adalah ....", opts:["12","10","11","13","14"], a:0, ex:"Jumlah sisi bertambah 2 tiap gambar: 6, 8, 10, 12 (segiduabelas). Banyak titik sudut = 12."},
{id:"TIU-1798", q:"Gambar ke-1 memuat segitiga yang di dalamnya terdapat 3 lingkaran kecil. Gambar ke-2 memuat segiempat yang di dalamnya terdapat 5 lingkaran kecil. Gambar ke-3 memuat segilima yang di dalamnya terdapat 7 lingkaran kecil. Banyak lingkaran kecil pada gambar ke-4 adalah ....", opts:["8","10","9","11","12"], a:2, ex:"Pola +2 mengikuti pertambahan sisi: 3, 5, 7, 9."},
{id:"TIU-1799", q:"Huruf 'd' dicerminkan terhadap garis horizontal menjadi huruf ....", opts:["p","b","d","u","q"], a:4, ex:"Pencerminan horizontal membalik atas-bawah: lengkung 'd' yang semula di bawah berpindah ke atas sehingga menjadi 'q'."},
{id:"TIU-1800", q:"Gambar ke-1 memuat lingkaran dengan bilangan 6 di atas, 4 di bawah, 5 di kiri, 3 di kanan, serta bilangan 9 di tengah. Gambar ke-2 memuat lingkaran dengan bilangan 8 di atas, 2 di bawah, 7 di kiri, 5 di kanan, serta bilangan 11 di tengah. Gambar ke-3 memuat lingkaran dengan bilangan 9 di atas, 5 di bawah, 8 di kiri, dan 4 di kanan. Bilangan di tengah gambar ke-3 adalah ....", opts:["11","12","13","14","15"], a:2, ex:"Tengah = (atas + bawah + kiri + kanan) ÷ 2: (6+4+5+3)÷2=9, (8+2+7+5)÷2=11, (9+5+8+4)÷2=13."}
];
